let dayRouteMap,dayRouteLayer,dayRouteLoading,dayRouteCoordinates,dayRouteRequest=0;
function loadDayRoute(){
 if(dayRouteLoading)return dayRouteLoading;
 dayRouteLoading=Promise.all([fetch('vendor/route-coordinates.json').then(r=>{if(!r.ok)throw Error();return r.json()}),new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='vendor/leaflet.css';css.onload=resolve;css.onerror=reject;document.head.append(css)}),new Promise((resolve,reject)=>{if(window.L)return resolve();const js=document.createElement('script');js.src='vendor/leaflet.js';js.onload=resolve;js.onerror=reject;document.head.append(js)})]).then(([coords])=>{dayRouteCoordinates=coords}).catch(e=>{dayRouteLoading=null;throw e});return dayRouteLoading;
}
async function openDayRoute(day){
 day=day||currentDay;const request=++dayRouteRequest;const dialog=document.getElementById('day-route-dialog');if(!dialog.open)dialog.showModal();document.querySelectorAll('[data-route-day]').forEach(b=>b.classList.toggle('active',Number(b.dataset.routeDay)===day));const status=document.getElementById('route-status');status.textContent='正在載入今日地圖…';
 try{await loadDayRoute();if(request!==dayRouteRequest||!dialog.open)return;
 if(!dayRouteMap){dayRouteMap=L.map('day-route-map');L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(dayRouteMap);dayRouteLayer=L.layerGroup().addTo(dayRouteMap)}
 dayRouteLayer.clearLayers();const list=document.getElementById('day-route-list');list.replaceChildren();const points=[];const cards=[...document.querySelectorAll('#day-'+day+' .card')];
 cards.forEach((card,i)=>{const title=card.querySelector('.item-title')?.textContent.trim()||'未命名行程';const placeInput=(card.dataset.mapPlaceInput||'').trim();const placeValue=(card.dataset.mapPlaceValue||'').trim();const raw=placeInput||placeValue||title;let coords=dayRouteCoordinates[placeInput]||dayRouteCoordinates[placeValue]||dayRouteCoordinates[title];if(!coords){const match=raw.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/);if(match)coords=[Number(match[1]),Number(match[2])];}const time=card.querySelector('.time-badge')?.textContent.trim()||'';const row=document.createElement('div');row.className='route-stop';const selectRow=()=>{list.querySelectorAll('.route-stop').forEach(el=>el.classList.remove('route-stop-selected'));row.classList.add('route-stop-selected');const top=row.getBoundingClientRect().top-list.getBoundingClientRect().top+list.scrollTop;list.scrollTo({top:Math.max(0,top-8),behavior:'smooth'});};const button=document.createElement('button');button.textContent=(i+1)+'. '+title;button.className='route-stop-title';const heading=document.createElement('div');heading.className='route-stop-heading';heading.append(button);row.append(heading);const meta=document.createElement('small');meta.textContent=time;const details=document.createElement('div');details.className='route-stop-details';details.append(meta);row.append(details);const nav=document.createElement('a');nav.className='route-nav-link btn-press-effect';nav.style.setProperty('display','inline-flex','important');nav.style.width='17px';nav.style.height='17px';nav.style.flex='0 0 17px';nav.style.border='0';nav.style.borderRadius='0';nav.style.background='transparent';nav.style.boxShadow='none';nav.style.padding='0';nav.style.marginLeft='4px';nav.style.opacity='.78';nav.setAttribute('aria-label','Google Maps 導航：'+title);nav.title='Google Maps 導航';nav.href=/^https:\/\//.test(raw)?raw:'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(raw);nav.target='_blank';nav.rel='noopener';nav.innerHTML='<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24"><path d="M12 21s6.5-6.1 6.5-11.2A6.5 6.5 0 0 0 5.5 9.8C5.5 14.9 12 21 12 21Z" fill="#d9ad9e"></path><path d="M12 21s6.5-6.1 6.5-11.2c0-2.1-1-4-2.6-5.2L9.5 18.7C10.8 20.1 12 21 12 21Z" fill="#b9c9b8"></path><path d="M6.5 13.5c.7 1.8 2 3.7 3.1 5.1l6.3-14A6.5 6.5 0 0 0 11.9 3L6.5 13.5Z" fill="#e4d09b"></path><circle cx="12" cy="9.6" fill="#fffaf7" r="2.45"></circle></svg>';const mapIcon=nav.querySelector('svg');mapIcon.style.width='14px';mapIcon.style.height='14px';mapIcon.style.filter='none';heading.append(nav);const back=document.createElement('button');back.textContent='查看行程';back.style.fontSize='12px';back.onclick=()=>{dialog.close();switchDay(day,{auto:true});setTimeout(()=>card.scrollIntoView({behavior:'smooth',block:'center'}),80)};details.append(back);list.append(row);
 if(coords){points.push(coords);const popup=document.createElement('div');const label=document.createElement('b');label.textContent=(i+1)+' · '+title;popup.append(label,document.createElement('br'),document.createTextNode(time),document.createElement('br'),nav.cloneNode(true));const marker=L.marker(coords,{icon:L.divIcon({className:'route-number',html:String(i+1),iconSize:[30,30],iconAnchor:[15,15]})}).bindPopup(popup).addTo(dayRouteLayer);marker.on('click',selectRow);button.onclick=()=>{selectRow();dayRouteMap.setView(coords,16);marker.openPopup()};}else{button.onclick=()=>{selectRow();nav.click()}}
 });
 if(points.length>1){L.polyline(points,{color:'#fffaf7',weight:8,opacity:.95,interactive:false}).addTo(dayRouteLayer);L.polyline(points,{color:'#c33f70',weight:4.5,opacity:1,interactive:false}).addTo(dayRouteLayer);}
 dayRouteMap.invalidateSize();const japan=points.filter(p=>p[1]>128);const bounds=japan.length?japan:points;if(bounds.length)dayRouteMap.fitBounds(bounds,{padding:[30,30],maxZoom:15});else dayRouteMap.setView([34.7,136.7],9);
 status.textContent='共 '+cards.length+' 項行程，清單順序與行程條一致。連線表示行程順序，不是實際道路；點編號查看景點。';
 }catch(e){status.textContent='地圖暫時無法載入，請確認網路後再點星期重試。'}
}
